local config = {
  ui_story_31870401_1_dialog_content = "Ah, PlayerName, você finalmente chegou.",
  ui_story_31870401_2_dialog_content = "Squawk está muito preocupado desde que Jabber desapareceu.",
  ui_story_31870401_3_dialog_content = "Grasna! Mais comida para mim!",
  ui_story_31870401_4_dialog_content = "Então o nome deste estorninho é Squawk?",
  ui_story_31870401_5_dialog_content = "Não parece particularmente preocupado...",
  ui_story_31870401_6_dialog_content = "Ah, o Squawk está falando bobagens de novo. Não dê ouvidos a isso.",
  ui_story_31870401_7_dialog_content = "Não, você está falando bobagens! Grasna!",
  ui_story_31870401_8_dialog_content = "Quieto, você! De qualquer forma, Jabber é o meu outro estorninho, aquele que se parece com o Squawk.",
  ui_story_31870401_9_dialog_content = "Então, você já viu por aqui?",
  ui_story_31870401_10_dialog_content = "Eu, ah... não consigo realmente me lembrar.",
  ui_story_31870401_11_dialog_content = "Talvez possamos começar lembrando onde você o perdeu?",
  ui_story_31870401_12_dialog_content = "Onde você esteve e o que você tem feito nos últimos dois dias?",
  ui_story_31870401_13_dialog_content = "Bem, agora que você mencionou, eu visitei muitos lugares nesse período de tempo.",
  ui_story_31870401_14_dialog_content = "Estou no meio de uma viagem por todo o Astra, coletando todos os tipos de fofocas e histórias estranhas...",
  ui_story_31870401_15_dialog_content = "E usando-os para concluir o terceiro capítulo do <color=#FFB400>\"Pergaminho da Ascensão Divina.\"</color>",
  ui_story_31870401_16_dialog_content = "O \"Pergaminho da Ascensão Divina\"? Parece bem complicado.",
  ui_story_31870401_17_dialog_content = "Isso é natural, considerando que essa obra misteriosa foi me dada por uma pessoa ainda mais misteriosa.",
  ui_story_31870401_18_dialog_content = "O primeiro capítulo é composto por <color=#FFB400>todos os tipos de lendas estranhas e antigas</color> de todo o mundo.",
  ui_story_31870401_19_dialog_content = "O segundo capítulo está repleto de <color=#FFB400>escritos e símbolos misteriosos</color>, todos completamente incompreensíveis...",
  ui_story_31870401_20_dialog_content = "Isso parece incrível! E o terceiro capítulo?",
  ui_story_31870401_21_dialog_content = "O terceiro capítulo... é uma coleção de <color=#FFB400>histórias estranhas e rumores</color> reunidos por mim mesmo!",
  ui_story_31870401_22_dialog_content = "E reservo todos os direitos para a explicação final do seu conteúdo.",
  ui_story_31870401_23_dialog_content = "(De alguma forma, sinto que isso não está fazendo justiça ao pergaminho...)",
  ui_story_31870401_24_dialog_content = "Ainda assim, gostaria que você lesse por si mesmo. Afinal, ver é acreditar.",
  ui_story_31870401_25_dialog_content = "Há apenas uma linha de texto em cada página do terceiro capítulo, então fique à vontade para dar uma olhada.",
  ui_story_31870401_26_dialog_content = "Certo, vamos ver...",
  ui_story_31870401_27_dialog_content = "<size=50>\"Preparações secretas para substituir o Grande Marechal estão bem encaminhadas\" ?!</size>",
  ui_story_31870401_28_dialog_content = "Esta parte significa que um certo Comandante Illumina de cabelo rosa tem secretamente imitado a caligrafia do Grande Marechal, entre outras coisas.",
  ui_story_31870401_29_dialog_content = "E... <size=50>\"Os segredos da corte real de Northland são expostos\"?! </size>",
  ui_story_31870401_30_dialog_content = "Ah, sim, essa parte. Isso apenas significa que a rainha de Northland tem o hábito de falar dormindo, entre outras coisas.",
  ui_story_31870401_31_dialog_content = "... Eu nunca ouvi falar sobre nenhuma dessas coisas! E por que você está fazendo tudo parecer tão mais sensacional do que realmente é?!",
  ui_story_31870401_32_dialog_content = "De qualquer forma, você deve estar bastante familiarizado com Astra agora que já esteve em tantos lugares, certo?",
  ui_story_31870401_33_dialog_content = "Minhas viagens são apenas parte do meu trabalho. Minha familiaridade com esta terra não é nada comparada à sua, tenho certeza.",
  ui_story_31870401_34_dialog_content = "Nos últimos dois dias, revisitei a <color=#FFB400>Baía dos Pavilhões Gêmeos</color>, o <color=#FFB400>Deserto Rediesel</color> e <color=#FFB400>Umbraton</color> para ouvir as fofocas mais recentes.",
  ui_story_31870401_35_dialog_content = "Você está familiarizado com algum desses lugares?",
  ui_story_31870401_36_dialog_content = "Tenho certeza de que alguém como você deve ter alguma técnica <color=#FFB400>especial</color> para encontrar pássaros, certo?",
  ui_story_31870401_37_dialog_content = "Como eu saberia? Eu não estava com você quando você...",
  ui_story_31870401_38_dialog_content = "Espere, entendi!",
  ui_story_31870401_39_option_content = "Use habilidades psíquicas",
  ui_story_31870401_40_dialog_content = "Posso usar meus poderes para ver suas memórias com base no conteúdo dessas três páginas.",
  ui_story_31870401_41_dialog_content = "Talvez eu consiga encontrar algumas pistas que nos levem até o Jabber!",
  ui_story_31870401_42_option_content = "Entre em contato com as partes envolvidas nas fofocas",
  ui_story_31870401_43_dialog_content = "Isso não vai funcionar, receio. Como um viajante colecionador de rumores do mundo, sempre lavo minhas mãos de assuntos antigos quando termino meus negócios.",
  ui_story_31870401_44_dialog_content = "Já sou grato o suficiente pelo fato de as partes envolvidas não terem tentado me caçar. Como eu poderia entrar em contato com eles?",
  ui_story_31870401_45_dialog_content = "Entendi... Acho que vou ter que usar meus poderes psíquicos, né?",
  ui_story_31870401_46_dialog_content = "Eu sabia que você era a pessoa certa para chamar.",
  ui_story_31870401_47_dialog_content = "Agora, você poderia começar com minhas lembranças de Twin Pavilions Bay?",
  ui_story_31870401_48_dialog_content = "Tudo bem, a parte sobre a Baía dos Pavilhões Gêmeos deve ser... <color=#FFB400>\"As tendências suspeitas do capitão do Shadowind?!\"</color>",
  ui_story_31870401_49_option_content = "Aumento de Força!",
  ui_story_31870401_50_dialog_content = "Ei, sou só eu ou o Capitão Yuebai tem agido estranho ultimamente?",
  ui_story_31870401_51_dialog_content = "Eu entendo o que você quer dizer. Ela tem saído sozinha nos últimos dias e, depois, verifica suas roupas toda vez que volta para a aeronave.",
  ui_story_31870401_52_dialog_content = "Ela provavelmente está verificando se não tem nada grudado em suas roupas. Eu aprendi há muito tempo que Umbraton está cheio de pessoas boas e ruins...",
  ui_story_31870401_53_dialog_content = "Ei, você acha possível que ela tenha sido comprada para ser informante daquele chefe de gangue?",
  ui_story_31870401_54_dialog_content = "Shh! Shh!",
  ui_story_31870401_55_dialog_content = "...",
  ui_story_31870401_56_dialog_content = "C-Capitão Yuebai!!",
  ui_story_31870401_57_dialog_content = "Oh? Estou sentindo cheiro de uma fofoca suculenta?",
  ui_story_31870401_58_dialog_content = "Yuebai está saindo!",
  ui_story_31870401_59_dialog_content = "Siga-a! Siga-a!",
  ui_story_31870401_60_dialog_content = "Eu sei, eu sei! Agora fala baixo!",
  ui_story_31870401_61_dialog_content = "<color=#e8d9bb>Baía dos Pavilhões Gêmeos</color>",
  ui_story_31870401_62_dialog_content = "...",
  ui_story_31870401_63_dialog_content = "Ela parece ter medo de ser notada. O que será que ela está tramando?",
  ui_story_31870401_64_dialog_content = "Ela está entrando em uma loja!",
  ui_story_31870401_65_dialog_content = "É uma taverna!",
  ui_story_31870401_66_dialog_content = "Será que esta é uma daquelas tavernas usadas para encontros clandestinos...?",
  ui_story_31870401_67_dialog_content = "Urgh?!",
  ui_story_31870401_68_dialog_content = "Eca, que fedor horrível!",
  ui_story_31870401_69_dialog_content = "Venham todos! Experimentem nosso delicioso <color=#FFB400>macarrão de caracol</color>, nosso novíssimo produto diretamente do oriente!",
  ui_story_31870401_70_dialog_content = "Um petisco saboroso apesar do cheiro, uma mordida te levará direto de volta a Longzhou!",
  ui_story_31870401_71_dialog_content = "O de sempre, por favor.",
  ui_story_31870401_72_dialog_content = "Entendi! Uma tigela de macarrão de caracol extra-picante com o dobro de caracóis e sem brotos de bambu em conserva, a caminho! Venha se sentar, amigo!",
  ui_story_31870401_73_dialog_content = "Ahhh, é impossível esquecer os aromas da culinária da nossa terra.",
  ui_story_31870401_74_dialog_content = "(Então o segredo de Yuebai é que ela gosta de sair escondida para comer macarrão de caracol...)",
  ui_story_31870401_75_dialog_content = "(Espera, o que estou fazendo? Eu deveria estar procurando pelo Jabber!)",
  ui_story_31870401_76_dialog_content = "Ainda assim, Jabber esteve com você nesta memória do começo ao fim.",
  ui_story_31870401_77_dialog_content = "Acho seguro dizer que você não o perdeu em Twin Pavilions Bay.",
  ui_story_31870401_78_dialog_content = "Entendi. Eu não fazia ideia de que seus poderes psíquicos permitiam que você visse as coisas tão claramente.",
  ui_story_31870401_79_dialog_content = "Agora, por favor, vire a próxima página e me ajude a procurar novamente.",
  ui_story_31870401_80_dialog_content = "Sem problemas. A próxima página é sobre... <color=#FFB400>\"A vida passada e presente de Lepidoz\"?!</color>",
  ui_story_31870401_81_option_content = "Aumento de Força!",
  ui_story_31870401_82_dialog_content = "<color=#e8d9bb>Deserto Rediesel</color>",
  ui_story_31870401_83_dialog_content = "Você nunca faz uma pausa?!",
  ui_story_31870401_84_dialog_content = "Também precisamos de comida e descanso!",
  ui_story_31870401_85_dialog_content = "Tenham modos, vocês dois! Eu tenho dado muitas frutas para vocês durante toda essa viagem!",
  ui_story_31870401_86_dialog_content = "Agora que temos fofocas tão interessantes sobre Yuebai, precisamos maximizar seu valor o mais rápido possível.",
  ui_story_31870401_87_dialog_content = "Sempre fui fascinado pelos Colossos desta terra.",
  ui_story_31870401_88_dialog_content = "Soroz—",
  ui_story_31870401_89_dialog_content = "Lepidoz—",
  ui_story_31870401_90_dialog_content = "E o navio mercante seria—",
  ui_story_31870401_91_dialog_content = "Sombras!",
  ui_story_31870401_92_dialog_content = "Navio mercante? Que navio mercante?",
  ui_story_31870401_93_dialog_content = "Ah sim, e às vezes as respostas que procuramos vêm caminhando diretamente até nós!",
  ui_story_31870401_94_dialog_content = "Hã? Não faço ideia do que você está falando, mas você veio para se juntar à Rediesel Wrench?",
  ui_story_31870401_95_dialog_content = "Não, eu apenas tenho o maior respeito e admiração pelo líder da Rediesel Wrench, e é por isso que vim aqui para relatar algumas novas informações.",
  ui_story_31870401_96_dialog_content = "Você fala engraçado, sabia? Além disso, o que tem de tão especial sobre Sinsa?",
  ui_story_31870401_97_dialog_content = "(Uh-oh, parece que estou lisonjeando a pessoa errada...)",
  ui_story_31870401_98_dialog_content = "(Vou ter que ajustar minha abordagem com base no que ele disse!)",
  ui_story_31870401_99_dialog_content = "Sabe, vendo o quão grande e poderoso você parece ser, tenho certeza de que seu líder confia em você com muitos dos segredos dele, não é?",
  ui_story_31870401_100_dialog_content = "Você tem um bom olho, cara! Acontece que eu sou o cara mais forte de toda a Rediesel Wrench!",
  ui_story_31870401_101_dialog_content = "Mas, uh... Que tipo de segredos você está falando?",
  ui_story_31870401_102_dialog_content = "Atualmente, tenho uma fofoca incrível relacionada ao capitão de um navio mercante da Família Lin. Você estaria interessado em trocar detalhes da existência de Lepidoz por isso?",
  ui_story_31870401_103_dialog_content = "Lepidoz, hein? Sinsa meio que encontrou e depois modificou pra caramba.",
  ui_story_31870401_104_dialog_content = "Não é realmente um segredo, considerando que as pessoas aqui adoram reaproveitar objetos velhos assim.",
  ui_story_31870401_105_dialog_content = "Quanto a onde encontramos o Lepidoz, eu não me importo de te contar também: quase tudo que recolhemos vem direto do <color=#FFB400>lixo</color>! Viva a Rediesel Wrench!",
  ui_story_31870401_106_dialog_content = "Lixo?",
  ui_story_31870401_107_dialog_content = "Isso mesmo! Seja um grande Colossus na beira da estrada ou um carro detonado... Tudo é válido aqui!",
  ui_story_31870401_108_dialog_content = "Afinal, liberdade é o que todos nós buscamos!",
  ui_story_31870401_109_dialog_content = "Isso me lembra... Qual navio mercante você estava falando? É um dos navios atracados no porto do continente?",
  ui_story_31870401_110_dialog_content = "Isso não é bom!",
  ui_story_31870401_111_dialog_content = "Corram, corram!",
  ui_story_31870401_112_dialog_content = "Hahaha! Desculpe, mas tenho que ir agora! Até a próxima, mano!",
  ui_story_31870401_113_dialog_content = "Na época, também foi um grande choque para mim.",
  ui_story_31870401_114_dialog_content = "(Então Sinsa foi quem modificou Lepidoz...)",
  ui_story_31870401_115_dialog_content = "(Argh, foco! Eu deveria estar procurando pelo Jabber!)",
  ui_story_31870401_116_dialog_content = "Jabber estava presente nesta memória o tempo todo também.",
  ui_story_31870401_117_dialog_content = "O grito dele soou tão estranho quanto o seu.",
  ui_story_31870401_118_dialog_content = "Estou surpreso que seus poderes psíquicos permitam que você também sinta os sentimentos do seu alvo...",
  ui_story_31870401_119_dialog_content = "Eu sei o que você vai dizer. Virar para a próxima página, certo?",
  ui_story_31870401_120_dialog_content = "Sim, por favor! Você é um adivinho por direito próprio, sabia?",
  ui_story_31870401_121_dialog_content = "Tudo bem, agora para a última página—<color=#FFB400>\"A grande revelação do aniversário da Princesa Zhuohua\"?! </color>",
  ui_story_31870401_122_option_content = "Aumento de Força!",
  ui_story_31870401_123_dialog_content = "Parece que os rumores em torno de Yuebai diminuíram mais ou menos agora.",
  ui_story_31870401_124_dialog_content = "Mesmo tendo derramado meu sangue, suor e lágrimas nesta tarefa, não consigo deixar de me sentir um pouco entediado com ela.",
  ui_story_31870401_125_dialog_content = "Se gabe disso, por que não?!",
  ui_story_31870401_126_dialog_content = "Uau, tão humilde!",
  ui_story_31870401_127_dialog_content = "Ah, todo esse falatório incessante realmente torna difícil se acalmar.",
  ui_story_31870401_128_dialog_content = "... Hum? Espere, acho que estou ouvindo algo além das suas vozes irritantes—",
  ui_story_31870401_129_dialog_content = "Ouvi dizer que o motivo pelo qual o capitão não faz negócios com Umbraton é porque aquele lugar é como o inferno descrito nas lendas.",
  ui_story_31870401_130_dialog_content = "Não apenas isso, dizem que o Senhor Sombrio tem chifres de touro e um rosto de cavalo, e que ele mantém um cachorro preto e um cachorro branco ao seu lado...",
  ui_story_31870401_131_dialog_content = "... E onde exatamente você ouviu essas coisas?",
  ui_story_31870401_132_dialog_content = "Mais histórias de bicho-papão, hein? Parece que essas pessoas estão apenas especulando sobre Umbraton, como antes.",
  ui_story_31870401_133_dialog_content = "Se eu não for para o inferno, quem mais irá?",
  ui_story_31870401_134_dialog_content = "<color=#e8d9bb>Umbraton</color>",
  ui_story_31870401_135_dialog_content = "Uma rua normal!",
  ui_story_31870401_136_dialog_content = "Uma loja normal!",
  ui_story_31870401_137_dialog_content = "Parece que os contos deste \"inferno\" foram muito exagerados.",
  ui_story_31870401_138_dialog_content = "... Ah? É um rosto familiar que vejo?",
  ui_story_31870401_139_dialog_content = "Majestade, esta barraca parece vender itens usados para o método de adivinhação de Astra.",
  ui_story_31870401_140_dialog_content = "Essas cartas... Acho que são chamadas de cartas de tarô? Interessante.",
  ui_story_31870401_141_dialog_content = "Jiu, eu quero tentar, ler minha sorte com eles.",
  ui_story_31870401_142_dialog_content = "Mas Sua Alteza...",
  ui_story_31870401_143_dialog_content = "Vamos escolher a carta ao lado da minha mão como a primeira.",
  ui_story_31870401_144_dialog_content = "Você poderia explicar o significado deste cartão, por favor?",
  ui_story_31870401_145_dialog_content = "Ah... Essa é a Torre na posição vertical. Não é um bom sinal, meu amigo.",
  ui_story_31870401_146_dialog_content = "Sua Alteza, tenho certeza de que isso é apenas um passatempo para passar o tempo, então por favor não...",
  ui_story_31870401_147_dialog_content = "Por favor, não coloque fé nisso de jeito nenhum.",
  ui_story_31870401_148_dialog_content = "Vejo que as ruas de Umbraton também não estão seguras de trapaceiros.",
  ui_story_31870401_149_dialog_content = "Mas nós somos ambos adivinhos, Princesa Zhuohua. Por que questionar minhas habilidades e não as deste cavalheiro?",
  ui_story_31870401_150_dialog_content = "Nunca fui de acreditar em adivinhos ou suas previsões infundadas. Eu te disse isso no navio, ou você esqueceu?",
  ui_story_31870401_151_dialog_content = "As tangerinas que crescem no sul são tangerinas!",
  ui_story_31870401_152_dialog_content = "Mas eles se tornariam laranjas amargas no norte!",
  ui_story_31870401_153_dialog_content = "Princesa Zhuohua, seria uma honra ler sua sorte, se você estiver disposta? Tenho certeza de que o método de adivinhação de nossa terra natal produzirá uma previsão muito diferente.",
  ui_story_31870401_154_dialog_content = "Tudo que eu preciso é do seu aniversário, e nada mais.",
  ui_story_31870401_155_dialog_content = "...",
  ui_story_31870401_156_dialog_content = "Muito bem então, estou curioso para ver que tipo de previsão mal elaborada você vai me dar.",
  ui_story_31870401_157_dialog_content = "O quarto dia do quarto mês... Realmente números especiais para sua data de nascimento, devo dizer.",
  ui_story_31870401_158_dialog_content = "Contemple os bastões, assuma o controle do destino. Com yin e yang combinados, todas as coisas ganham forma...",
  ui_story_31870401_159_dialog_content = "Nossa. Essa é a primeira vez que vejo um destino tão incrivelmente bizarro.",
  ui_story_31870401_160_dialog_content = "Poupe-nos das teatralidades e apenas diga minha sorte.",
  ui_story_31870401_161_dialog_content = "A Serpente Yang e o Tigre Yin são uma fortuna também conhecida como \"cabeça de cobra e cauda de tigre\", onde a cobra representa a luz e o tigre representa a escuridão.",
  ui_story_31870401_162_dialog_content = "Por mais absurdo que possa parecer, essa sorte na verdade contém um significado profundo.",
  ui_story_31870401_163_dialog_content = "Pelo que posso ver, seu destino é repleto de muitas lutas, mas no final da sua jornada há uma bifurcação no caminho, e além disso está a <color=#FFB400>boa sorte</color>.",
  ui_story_31870401_164_dialog_content = "O quê?!",
  ui_story_31870401_165_dialog_content = "Mas quando eu era criança, a vidente me disse que eu estava destinado a ter azar...",
  ui_story_31870401_166_dialog_content = "Destino e sorte são duas coisas muito diferentes. O destino é decidido pelos céus, enquanto a sorte pode ser mudada por nossas próprias mãos.",
  ui_story_31870401_167_dialog_content = "Caso decida continuar no seu caminho atual, a vida vai melhorar. As coisas não serão tão ruins quanto eram antes, tenho certeza.",
  ui_story_31870401_168_dialog_content = "Quanto a quando isso acontecerá, não posso dizer. Afinal, certas coisas devem permanecer em segredo.",
  ui_story_31870401_169_dialog_content = "No entanto, isso é apenas minha própria previsão. Você é livre para acreditar em qualquer uma das previsões dadas a você ou em nenhuma delas.",
  ui_story_31870401_170_dialog_content = "Agora preciso ir. Até a próxima vez que nos encontrarmos, Alteza.",
  ui_story_31870401_171_dialog_content = "Adeus!",
  ui_story_31870401_172_dialog_content = "Até a próxima!",
  ui_story_31870401_173_dialog_content = "...",
  ui_story_31870401_174_dialog_content = "Sua Alteza... Em que está pensando?",
  ui_story_31870401_175_dialog_content = "... Não é nada. Vamos Jiu, devemos voltar para o navio agora.",
  ui_story_31870401_176_dialog_content = "Ah, parece que o destino da Princesa Zhuohua está longe de ser comum. Os céus colocaram uma grande responsabilidade sobre os ombros dela.",
  ui_story_31870401_177_dialog_content = "(Então foi esse tipo de sorte que Dantang recebeu ao nascer...)",
  ui_story_31870401_178_dialog_content = "(Oh, não de novo! Tenho que encontrar o Jabber!)",
  ui_story_31870401_179_dialog_content = "Sem pistas nesta página também, então acho que vou ter que tentar a próxima...",
  ui_story_31870401_180_dialog_content = "Pare! Não vire essa página!",
  ui_story_31870401_181_dialog_content = "Hã?",
  ui_story_31870401_182_dialog_content = "Eu sugiro fortemente que você não leia mais, PlayerName. Como eu disse antes, certas coisas devem ser mantidas em segredo.",
  ui_story_31870401_183_dialog_content = "Tudo bem, seja todo misterioso então...",
  ui_story_31870401_184_dialog_content = "Por favor, me perdoe, principalmente quando eu deveria estar agradecendo por usar seus poderes psíquicos para me ajudar.",
  ui_story_31870401_185_dialog_content = "Acho que sei onde encontrar o Jabber agora.",
  ui_story_31870401_186_dialog_content = "O quê? Você faz?!",
  ui_story_31870401_187_dialog_content = "Mas não consegui descobrir nada...",
  ui_story_31870401_188_dialog_content = "Por mais que eu gostaria de te acompanhar, preciso procurar o Jabber imediatamente. Com certeza agradecerei adequadamente em outra ocasião.",
  ui_story_31870401_189_dialog_content = "Não se preocupe com isso. Não é como se eu realmente tivesse feito algo...",
  ui_story_31870401_190_dialog_content = "Tchau por agora! Até a próxima!",
  ui_story_31870401_191_dialog_content = "E-Eu vou indo então!",
  ui_story_31870401_192_dialog_content = "<color=#e8d9bb>Algum tempo depois</color>",
  ui_story_31870401_193_dialog_content = "...",
  ui_story_31870401_194_dialog_content = "Tudo bem, vocês dois podem sair agora.",
  ui_story_31870401_195_dialog_content = "Uma única prancha não faz um barco!",
